open System
open System.Collections.Generic

type Cell = {
    X: int
    Y: int
    GasConcentration: float
}

let gridSize = 100
let initialGasConcentration = 1.0
let initialGasPosition = { X = gridSize / 2; Y = gridSize / 2; GasConcentration = initialGasConcentration }
let diffusionRate = 0.01

let random = new Random()

let neighbors (cell: Cell) =
    [
        { cell with X = cell.X - 1; Y = cell.Y }
        { cell with X = cell.X + 1; Y = cell.Y }
        { cell with X = cell.X; Y = cell.Y - 1 }
        { cell with X = cell.X; Y = cell.Y + 1 }
    ]
    |> List.filter (fun neighbor -> 0 <= neighbor.X && neighbor.X < gridSize && 0 <= neighbor.Y && neighbor.Y < gridSize)

let updateCell (cell: Cell) (neighborsGasConcentration: float list) =
    let totalGas = cell.GasConcentration + (List.sum neighborsGasConcentration)
    let newGasConcentration = totalGas / (float neighbors.Length + 1.0)
    { cell with GasConcentration = newGasConcentration }

let updateGrid (grid: List<Cell>) =
    let newGrid = List.create gridSize (List.create gridSize { X = i; Y = j; GasConcentration = 0.0 })
    for cell in grid do
        let neighborsGasConcentration =
            neighbors cell
            |> List.map (fun neighbor -> grid |> List.tryFind (fun n -> n.X = neighbor.X && n.Y = neighbor.Y) |> Option.map (fun n -> n.GasConcentration))
            |> List.choose id
        newGrid.[cell.X].[cell.Y] <- updateCell cell neighborsGasConcentration
    newGrid

let main() =
