    for _ in 1 .. 100 do
        initialGrid <- updateGrid initialGrid
        Console.Clear()
        for y = 0 to gridSize - 1 do
            for x = 0 to gridSize - 1 do
                let cell = initialGrid |> List.tryFind (fun c -> c.X = x && c.Y = y)
                if cell.IsSome then
