To create a C++ program that connects to a POP3 server and retrieves emails, you can use the Boost.Asio library. Here's a simple example:

```cpp
#include <boost/asio.hpp>
#include <iostream>
#include <string>

namespace asio = boost::asio;

void pop3_login(asio::io_context& io_context, const std::string& host, const std::string& user, const std::string& password) {
    asio::ip::tcp::resolver resolver(io_context);
    asio::ip::tcp::resolver::query query(asio::ip::tcp::v4(), host, "pop3");
    asio::ip::tcp::resolver::iterator iterator = resolver.resolve(query);

    asio::ip::tcp::socket socket(io_context);
    asio::connect(socket, iterator);

    asio::streambuf request;
    std::ostream request_stream(&request);
    request_stream << "USER " << user << "\r\n";
    asio::write(socket, request.data(), request.size());

    char buffer[1024];
    asio::read_until(socket, request, "\r\n");
    std::istream response_stream(&request);
    response_stream.get(); // discard the response code
    response_stream.getline(buffer, sizeof(buffer)); // get the response message
    std::cout << "Response: " << buffer << std::endl;

    request_stream << "PASS " << password << "\r\n";
    asio::write(socket, request.data(), request.size());

    asio::read_until(socket, request, "\r\n");
    response_stream.get(); // discard the response code
    response_stream.getline(buffer, sizeof(buffer)); // get the response message
    std::cout << "Response: " << buffer << std::endl;
}

int main(int argc, char* argv[]) {
    try {
        if (argc != 4) {
            std::cerr << "Usage: pop3_client <host> <user> <password>\n";
            return 1;
        }

        asio::io_context io_context;
        pop3_login(io_context, argv[1], argv[2], argv[3]);

        io_context.run();
    } catch (std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
        return 1;
    }

    return 0;
}
```

